action.command:
python3 -c "
import sys, json, os
try:
    data = json.load(sys.stdin)
except Exception:
    sys.exit(0)
file_path = data.get('filePath') or data.get('file') or data.get('path') or ''
if not file_path:
    sys.exit(0)
if not os.path.isfile(file_path):
    sys.exit(0)
if os.path.getsize(file_path) == 0:
    print(f'ERROR: {file_path} is empty - Pelican will skip this article. Add content and save again.', file=sys.stderr)
    sys.exit(2)
"
